from ortools.sat.python import cp_model
import json

def solve_camera_placement():
    I = list(range(10))
    R = [
        (0, 1), (0, 2), (0, 3),
        (1, 4), (1, 5),
        (2, 6), (2, 7),
        (3, 8), (3, 9),
        (4, 5), (6, 7), (8, 9),
        (4, 6), (5, 8), (7, 9)
    ]

    model = cp_model.CpModel()

    x = {}
    for i in I:
        x[i] = model.NewBoolVar(f"x_{i}")

    for i, j in R:
        model.Add(x[i] + x[j] >= 1)

    model.Minimize(sum(x[i] for i in I))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 0

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        selected_intersections = [i for i in I if solver.Value(x[i]) == 1]
        num_cameras = len(selected_intersections)

        print(json.dumps({
            "selected_intersections": selected_intersections,
            "num_cameras": num_cameras
        }))
    else:
        print(json.dumps({
            "selected_intersections": [],
            "num_cameras": 0
        }))

if __name__ == "__main__":
    solve_camera_placement()
